from tkinter import *
screen = Tk()
screen.geometry('500x250')
lable = Label(screen, text='Weight Converter', font='georgia 50')
lable.pack(side='top')
entry = Entry(screen, bg='Grey')
entry.place(x=50, y=120)
eentry = Entry(screen)
eentry.place(x=250, y=120)
eentry = Entry(screen)
eentry.place(x=50, y=170)
eeentry = Entry(screen)
eeentry.place(x=250, y=170)
label = Label(screen, text='Pounds')
label.place(x=320, y=100)
labell = Label(screen, text='Grams')
labell.place(x=120, y=100)
llabel = Label(screen, text='Kilograms')
llabel.place(x=320, y=150)
llabell = Label(screen, text='Ounces')
llabell.place(x=120, y=150)
def thecommand():
    grams = int(entry.get())
    kilograms = 1000*grams
    '''eeentry.delete(0, )'''
    eeentry.delete(0, END)
    eeentry.insert(0, kilograms)
    pounds = grams*2.20462
    entry.insert(0, pounds)

button = Button(screen, text='  Press Me!   ', command=thecommand)
button.place(x=190, y=90)
screen.mainloop()